          ok: false,
          code: 'stale_ref',
          message: 'ref=' + ref + ' was <' + fp.tag + '>' + (fp.text ? '"' + fp.text + '"' : '')
            + ' but now points to <' + liveFp.tag + '>' + (liveFp.text ? '"' + liveFp.text.slice(0, 30) + '"' : ''),
          hint: 'The page has changed since the last snapshot. Re-run `opencli browser state` to refresh.',
        };
      }

